#include <SDL2/SDL.h>
#include <GLES2/gl2.h>
#include <GLES2/gl2ext.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <sys/resource.h>
#define MAX 16384
#define CHECK(c) do{if(!(c)){fprintf(stderr,"error line %d: %s SDL=%s GL=%x\n",__LINE__,#c,SDL_GetError(),glGetError());exit(2);}}while(0)
typedef struct{float p[3],c[4],uvq[3];} Vertex;
typedef struct{uint32_t resource,first,count;int box[4];int degenerate;} Draw;
typedef struct{int w,h;GLuint texture;unsigned char*p;} Texture;
static Vertex *vertices;static unsigned nv,nd,nr;static Draw original[MAX],grouped[MAX];static unsigned ng;static Texture textures[MAX];static float bg[3];static int priority,depth;
static GLuint vbo,stream_vbo,ebo,framebuffer,program;static unsigned *indices;static size_t texture_bytes;static unsigned char *reference;
static double stamp(clockid_t id){struct timespec t;clock_gettime(id,&t);return t.tv_sec+t.tv_nsec*1e-9;}
static const char *vs="uniform mat4 projection;attribute vec3 p;attribute vec4 c;attribute vec3 uvq;varying mediump vec4 color;varying highp vec3 coords;void main(){gl_Position=projection*vec4(p,1.0);color=c;coords=uvq;}";
static const char *fs="precision highp float;uniform sampler2D tex;uniform bool priority;varying mediump vec4 color;varying highp vec3 coords;void main(){vec4 t=texture2D(tex,coords.xy/coords.z);if(t.a==0.0)discard;vec4 c=color*t;gl_FragColor=priority?vec4(c.rgb,color.a):c;}";
static GLuint make_program(void){GLuint p=glCreateProgram();const char*s[]={vs,fs};for(int i=0;i<2;i++){GLuint q=glCreateShader(i?GL_FRAGMENT_SHADER:GL_VERTEX_SHADER);glShaderSource(q,1,s+i,NULL);glCompileShader(q);GLint ok;glGetShaderiv(q,GL_COMPILE_STATUS,&ok);if(!ok){char msg[4096];glGetShaderInfoLog(q,sizeof msg,NULL,msg);fprintf(stderr,"%s\n",msg);}CHECK(ok);glAttachShader(p,q);glDeleteShader(q);}glBindAttribLocation(p,0,"p");glBindAttribLocation(p,1,"c");glBindAttribLocation(p,2,"uvq");glLinkProgram(p);GLint ok;glGetProgramiv(p,GL_LINK_STATUS,&ok);CHECK(ok);return p;}
static GLuint texture(int w,int h,const void*p){GLuint t;glGenTextures(1,&t);glBindTexture(GL_TEXTURE_2D,t);glTexParameteri(GL_TEXTURE_2D,GL_TEXTURE_MIN_FILTER,GL_NEAREST);glTexParameteri(GL_TEXTURE_2D,GL_TEXTURE_MAG_FILTER,GL_NEAREST);glTexParameteri(GL_TEXTURE_2D,GL_TEXTURE_WRAP_S,GL_CLAMP_TO_EDGE);glTexParameteri(GL_TEXTURE_2D,GL_TEXTURE_WRAP_T,GL_CLAMP_TO_EDGE);glTexImage2D(GL_TEXTURE_2D,0,GL_RGBA,w,h,0,GL_RGBA,GL_UNSIGNED_BYTE,p);return t;}
static FILE*open_file(const char*dir,const char*name){char path[4096];CHECK(snprintf(path,sizeof path,"%s/%s",dir,name)<sizeof path);FILE*f=fopen(path,"rb");CHECK(f);return f;}
static void load(const char*dir){FILE*f=open_file(dir,"scene.meta");CHECK(fscanf(f,"%f %f %f %d %d",bg,bg+1,bg+2,&priority,&depth)==5);fclose(f);CHECK(depth==16||depth==24);CHECK(priority==0||priority==1);f=open_file(dir,"draws.bin");uint32_t h[6];size_t header_bytes;while((header_bytes=fread(h,1,24,f))==24){CHECK(nd<MAX&&h[0]<MAX&&h[1]&&h[1]%3==0&&h[1]<=60000);Draw*d=original+nd++;d->resource=h[0];d->first=nv;d->count=h[1];memcpy(d->box,h+2,16);CHECK(nv+h[1]<=1000000);vertices=realloc(vertices,(nv+h[1])*sizeof(Vertex));CHECK(vertices);CHECK(fread(vertices+nv,sizeof(Vertex),h[1],f)==h[1]);nv+=h[1];if(h[0]+1>nr)nr=h[0]+1;}CHECK(header_bytes==0&&feof(f));fclose(f);CHECK(nd&&nv);for(unsigned i=0;i<nr;i++){char name[80];snprintf(name,sizeof name,"texture-%u.rgba",i);f=open_file(dir,name);Texture*r=textures+i;CHECK(fscanf(f,"%d %d",&r->w,&r->h)==2);CHECK(fgetc(f)=='\n');CHECK(r->w>0&&r->w<=4096&&r->h>0&&r->h<=4096);size_t n=(size_t)r->w*r->h*4;r->p=malloc(n);CHECK(r->p&&fread(r->p,1,n,f)==n&&fgetc(f)==EOF);fclose(f);texture_bytes+=n;r->texture=texture(r->w,r->h,r->p);}f=open_file(dir,"reference.rgba");reference=malloc(640*480*4);CHECK(reference&&fread(reference,4,640*480,f)==640*480);fclose(f);}
static int cmpdraw(const void*a,const void*b){const Draw*x=a,*y=b;if(x->resource!=y->resource)return x->resource<y->resource?-1:1;int bcmp=memcmp(x->box,y->box,16);if(bcmp)return bcmp;return x->first<y->first?-1:x->first!=y->first;}
static void prepare(void){CHECK(priority);double minsep=1e9;float *zs=malloc(nv*sizeof(float));unsigned nz=0;for(unsigned i=0;i<nv;i++){CHECK(vertices[i].p[2]>-1&&vertices[i].p[2]<1);int found=0;for(unsigned j=0;j<nz;j++)if(zs[j]==vertices[i].p[2]){found=1;break;}if(!found)zs[nz++]=vertices[i].p[2];}for(unsigned i=0;i<nz;i++)for(unsigned j=i+1;j<nz;j++){double delta=fabs((double)zs[i]-zs[j])*65535/2;if(delta<minsep)minsep=delta;}free(zs);CHECK(minsep>2);printf("DEPTH unique=%u min_separation_16bit_lsb=%.6f\n",nz,minsep);
Draw sorted[MAX];memcpy(sorted,original,nd*sizeof(Draw));for(unsigned i=0;i<nd;i++){Draw*d=sorted+i;for(unsigned j=0;j<d->count;j+=3){Vertex*a=vertices+d->first+j,*b=a+1,*c=a+2;double area=((double)b->p[0]-a->p[0])*((double)c->p[1]-a->p[1])-((double)c->p[0]-a->p[0])*((double)b->p[1]-a->p[1]);if(area==0)d->degenerate=1;}}
qsort(sorted,nd,sizeof(Draw),cmpdraw);indices=malloc(nv*sizeof(unsigned));CHECK(indices);unsigned cursor=0;for(unsigned i=0;i<nd;i++){Draw*d=sorted+i;int merge=ng&&!d->degenerate&&!grouped[ng-1].degenerate&&grouped[ng-1].resource==d->resource&&!memcmp(grouped[ng-1].box,d->box,16);if(merge)grouped[ng-1].count+=d->count;else{grouped[ng]=*d;grouped[ng++].first=cursor;}for(unsigned j=0;j<d->count;j++)indices[cursor++]=d->first+j;}CHECK(cursor==nv);glGenBuffers(1,&stream_vbo);glGenBuffers(1,&vbo);glBindBuffer(GL_ARRAY_BUFFER,vbo);glBufferData(GL_ARRAY_BUFFER,nv*sizeof(Vertex),vertices,GL_STATIC_DRAW);glGenBuffers(1,&ebo);glBindBuffer(GL_ELEMENT_ARRAY_BUFFER,ebo);glBufferData(GL_ELEMENT_ARRAY_BUFFER,nv*sizeof(unsigned),indices,GL_STATIC_DRAW);printf("ASSETS resources=%u original_draws=%u resident_draws=%u vertices=%u texture_bytes=%zu vertex_bytes=%zu index_bytes=%zu steady_upload_bytes=0\n",nr,nd,ng,nv,texture_bytes,nv*sizeof(Vertex),nv*sizeof(unsigned));}
static void draw(int mode,double*cpu,double*submit,double*complete){double t=stamp(CLOCK_MONOTONIC),c=stamp(CLOCK_THREAD_CPUTIME_ID);glBindFramebuffer(GL_FRAMEBUFFER,framebuffer);glViewport(0,0,640,480);glDisable(GL_CULL_FACE);glDisable(GL_BLEND);glDisable(GL_SCISSOR_TEST);glEnable(GL_DEPTH_TEST);glDepthFunc(GL_LEQUAL);glDepthMask(GL_TRUE);glClearColor(bg[0],bg[1],bg[2],0);glClearDepthf(1);glClear(GL_COLOR_BUFFER_BIT|GL_DEPTH_BUFFER_BIT);glEnable(GL_SCISSOR_TEST);glUseProgram(program);const float matrix[16]={2.f/640,0,0,0,0,-2.f/480,0,0,0,0,1,0,-1,1,0,1};glUniformMatrix4fv(glGetUniformLocation(program,"projection"),1,GL_FALSE,matrix);glUniform1i(glGetUniformLocation(program,"tex"),0);glUniform1i(glGetUniformLocation(program,"priority"),priority);glActiveTexture(GL_TEXTURE0);glBindBuffer(GL_ARRAY_BUFFER,mode==0?stream_vbo:vbo);if(mode==0)glBufferData(GL_ARRAY_BUFFER,nv*sizeof(Vertex),vertices,GL_STREAM_DRAW);for(int i=0;i<3;i++)glEnableVertexAttribArray(i);glVertexAttribPointer(0,3,GL_FLOAT,GL_FALSE,40,(void*)0);glVertexAttribPointer(1,4,GL_FLOAT,GL_FALSE,40,(void*)12);glVertexAttribPointer(2,3,GL_FLOAT,GL_FALSE,40,(void*)28);Draw*ds=mode==2?grouped:original;unsigned n=mode==2?ng:nd;glBindBuffer(GL_ELEMENT_ARRAY_BUFFER,ebo);for(unsigned i=0;i<n;i++){Draw*d=ds+i;glBindTexture(GL_TEXTURE_2D,textures[d->resource].texture);glScissor(d->box[0],d->box[1],d->box[2],d->box[3]);if(mode==2)glDrawElements(GL_TRIANGLES,d->count,GL_UNSIGNED_INT,(void*)((size_t)d->first*4));else glDrawArrays(GL_TRIANGLES,d->first,d->count);}*cpu=stamp(CLOCK_THREAD_CPUTIME_ID)-c;*submit=stamp(CLOCK_MONOTONIC)-t;glFinish();*complete=stamp(CLOCK_MONOTONIC)-t;CHECK(glGetError()==GL_NO_ERROR);}
static unsigned diff(const unsigned char*a,const unsigned char*b){unsigned n=0;for(unsigned i=0;i<640*480;i++)n+=memcmp(a+i*4,b+i*4,4)!=0;return n;}
int main(int argc,char**argv){CHECK(argc==3);int samples=atoi(argv[2]);CHECK(samples>0&&samples<=200);double begin=stamp(CLOCK_MONOTONIC);CHECK(SDL_Init(SDL_INIT_VIDEO)==0);SDL_GL_SetAttribute(SDL_GL_CONTEXT_PROFILE_MASK,SDL_GL_CONTEXT_PROFILE_ES);SDL_GL_SetAttribute(SDL_GL_CONTEXT_MAJOR_VERSION,2);SDL_GL_SetAttribute(SDL_GL_DEPTH_SIZE,24);SDL_Window*w=SDL_CreateWindow("Native frozen scene diagnostic",0,0,640,480,SDL_WINDOW_OPENGL);CHECK(w&&SDL_GL_CreateContext(w));SDL_GL_SetSwapInterval(0);const char*ext=(const char*)glGetString(GL_EXTENSIONS);CHECK(strstr((char*)glGetString(GL_VERSION),"OpenGL ES 3")||strstr(ext,"GL_OES_element_index_uint"));printf("GPU %s VERSION %s\n",glGetString(GL_RENDERER),glGetString(GL_VERSION));GLint units,maxtex;glGetIntegerv(GL_MAX_TEXTURE_IMAGE_UNITS,&units);glGetIntegerv(GL_MAX_TEXTURE_SIZE,&maxtex);printf("FEATURES units=%d max_texture=%d depth_requested=24\n",units,maxtex);load(argv[1]);prepare();program=make_program();GLuint target=texture(640,480,NULL),db;glGenFramebuffers(1,&framebuffer);glBindFramebuffer(GL_FRAMEBUFFER,framebuffer);glFramebufferTexture2D(GL_FRAMEBUFFER,GL_COLOR_ATTACHMENT0,GL_TEXTURE_2D,target,0);glGenRenderbuffers(1,&db);glBindRenderbuffer(GL_RENDERBUFFER,db);glRenderbufferStorage(GL_RENDERBUFFER,depth==24?GL_DEPTH_COMPONENT24_OES:GL_DEPTH_COMPONENT16,640,480);glFramebufferRenderbuffer(GL_FRAMEBUFFER,GL_DEPTH_ATTACHMENT,GL_RENDERBUFFER,db);CHECK(glCheckFramebufferStatus(GL_FRAMEBUFFER)==GL_FRAMEBUFFER_COMPLETE);glFinish();printf("LOAD wall_ms=%.6f\n",(stamp(CLOCK_MONOTONIC)-begin)*1000);unsigned char*base=malloc(640*480*4),*pixels=malloc(640*480*4);CHECK(base&&pixels);double cpu,sub,complete;unsigned failure=0;for(int mode=0;mode<3;mode++){draw(mode,&cpu,&sub,&complete);glReadPixels(0,0,640,480,GL_RGBA,GL_UNSIGNED_BYTE,pixels);if(!mode)memcpy(base,pixels,640*480*4);unsigned n=diff(base,pixels);printf("VERIFY mode=%d vs_original=%u vs_capture=%u\n",mode,n,diff(reference,pixels));failure+=n;char path[80];snprintf(path,sizeof path,"mode-%d.rgba",mode);FILE*f=fopen(path,"wbx");CHECK(f&&fwrite(pixels,4,640*480,f)==640*480);fclose(f);}CHECK(!failure);for(int i=0;i<5;i++)for(int m=0;m<3;m++)draw(m,&cpu,&sub,&complete);for(int i=0;i<samples;i++)for(int j=0;j<3;j++){int m=(i+j)%3;draw(m,&cpu,&sub,&complete);printf("TIMING sample=%d mode=%d cpu_ms=%.6f submission_ms=%.6f completion_ms=%.6f\n",i,m,cpu*1000,sub*1000,complete*1000);}struct rusage usage;getrusage(RUSAGE_SELF,&usage);printf("RSS max_kib=%ld\n",usage.ru_maxrss);SDL_Quit();return 0;}
